1	package agentusage
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"reflect"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// Tests of Activity and Settled (DEVDESK-44 step 5, criterion 1): a finished
14	// session is no longer read periodically. Decisions: Settled needs no
15	// sub-agent with finished:false and no change for `quiet`; a StateUnknown
16	// sub-agent does not keep the session active. The clock is injected through
17	// timeNow and explicit mtimes: nothing sleeps.
18	
19	const actQuiet = 5 * time.Minute
20	
21	// actBase is the instant the fake clock starts at.
22	var actBase = time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
23	
24	// metaUnknown has no finished key, so its state is StateUnknown.
25	const metaUnknown = `{"agentType":"coder"}`
26	
27	// setClock stubs timeNow with a clock the test moves by assigning *now.
28	func setClock(t *testing.T, at time.Time) *time.Time {
29		t.Helper()
30		now := at
31		orig := timeNow
32		timeNow = func() time.Time { return now }
33		t.Cleanup(func() { timeNow = orig })
34		return &now
35	}
36	
37	// touch sets a file's mtime.
38	func touch(t *testing.T, path string, at time.Time) {
39		t.Helper()
40		if err := os.Chtimes(path, at, at); err != nil {
41			t.Fatal(err)
42		}
43	}
44	
45	// putAt writes a file with the given mtime.
46	func (s *sess) putAt(path string, data []byte, at time.Time) {
47		s.t.Helper()
48		s.put(path, data)
49		touch(s.t, path, at)
50	}
51	
52	// metaSet describes a session: the meta body of each sub-agent ("" = no meta).
53	type metaSet map[string]string
54	
55	// build lays the session out with every file's mtime at `at`.
56	func (s *sess) build(metas metaSet, at time.Time) {
57		s.t.Helper()
58		s.putAt(s.parent(), cat(ln("p1"), ln("p2")), at)
59		for id, body := range metas {
60			s.putAt(s.sub(id), ln("s-"+id), at)
61			if body != "" {
62				s.putAt(s.metaPath(id), []byte(body), at)
63			}
64		}
65	}
66	
67	func TestActivityBeforeAnyApplyIsZero(t *testing.T) {
68		setClock(t, actBase)
69		s := newSess(t)
70		s.build(metaSet{"a1": metaUnfinished}, actBase)
71		a := NewAggregate(s.parent())
72		nows := []time.Time{{}, actBase, actBase.Add(actQuiet), actBase.Add(1000 * time.Hour)}
73		check := func(stage string) {
74			t.Helper()
75			if got := a.Activity(); got != (Activity{}) {
76				t.Errorf("%s: Activity = %+v, want the zero value", stage, got)
77			}
78			for _, now := range nows {
79				for _, q := range []time.Duration{0, actQuiet} {
80					if a.Activity().Settled(now, q) {
81						t.Errorf("%s: Settled(%v, %v) = true, want false", stage, now, q)
82					}
83				}
84			}
85		}
86		check("new aggregate")
87		d, err := ReadDelta(a.Cursor())
88		if err != nil {
89			t.Fatal(err)
90		}
91		check("delta read but not applied")
92		if err := a.Apply(d); err != nil {
93			t.Fatal(err)
94		}
95		if err := a.Apply(d); !errors.Is(err, ErrStaleDelta) {
96			t.Fatalf("second Apply = %v, want ErrStaleDelta", err)
97		}
98		if a.Activity() == (Activity{}) {
99			t.Error("a stale Apply must not wipe the activity of the first one")
100		}
101	}
102	
103	func TestSettledTable(t *testing.T) {
104		last := actBase
105		tests := []struct {
106			name string
107			act  Activity
108			now  time.Time
109			want bool
110		}{
111			{"exactly quiet, nothing unfinished", Activity{LastChange: last}, last.Add(actQuiet), true},
112			{"one ns short of quiet", Activity{LastChange: last}, last.Add(actQuiet - time.Nanosecond), false},
113			{"long past quiet", Activity{LastChange: last}, last.Add(100 * time.Hour), true},
114			{"fresh change", Activity{LastChange: last}, last, false},
115			{"unfinished blocks at any age", Activity{LastChange: last, Unfinished: 1}, last.Add(1000 * time.Hour), false},
116			{"several unfinished", Activity{LastChange: last, Unfinished: 3}, last.Add(1000 * time.Hour), false},
117			{"zero LastChange is never settled", Activity{}, last.Add(1000 * time.Hour), false},
118			{"clock before the last change", Activity{LastChange: last}, last.Add(-time.Hour), false},
119		}
120		for _, tc := range tests {
121			t.Run(tc.name, func(t *testing.T) {
122				if got := tc.act.Settled(tc.now, actQuiet); got != tc.want {
123					t.Errorf("%+v.Settled(%v, %v) = %v, want %v", tc.act, tc.now, actQuiet, got, tc.want)
124				}
125			})
126		}
127	}
