129	// Q2 A: only finished:false counts; unknown, finished, and a sub-agent with
130	// no (or unreadable) meta do not.
131	func TestActivityUnfinishedCount(t *testing.T) {
132		tests := []struct {
133			name  string
134			metas metaSet
135			want  int
136		}{
137			{"no sub-agent", nil, 0},
138			{"one unfinished", metaSet{"a1": metaUnfinished}, 1},
139			{"one finished", metaSet{"a1": metaFinished}, 0},
140			{"one unknown", metaSet{"a1": metaUnknown}, 0},
141			{"finished is not a boolean", metaSet{"a1": `{"agentType":"coder","finished":"no"}`}, 0},
142			{"no meta file", metaSet{"a1": ""}, 0},
143			{"mixed", metaSet{"a1": metaUnfinished, "b2": metaFinished, "c3": metaUnknown, "d4": metaUnfinished, "e5": ""}, 2},
144		}
145		for _, tc := range tests {
146			t.Run(tc.name, func(t *testing.T) {
147				setClock(t, actBase)
148				s := newSess(t)
149				s.build(tc.metas, actBase)
150				a := NewAggregate(s.parent())
151				readApply(t, a)
152				act := a.Activity()
153				if act.Unfinished != tc.want {
154					t.Errorf("Unfinished = %d, want %d", act.Unfinished, tc.want)
155				}
156				far := actBase.Add(100 * time.Hour)
157				if got, want := act.Settled(far, actQuiet), tc.want == 0; got != want {
158					t.Errorf("Settled(far) = %v, want %v", got, want)
159				}
160			})
161		}
162	}
