164	// The plan: LastChange is the newest mtime among the parent, the sub-agents
165	// and the metas, clamped to the time of the read.
166	func TestActivityLastChangeIsTheNewestMtime(t *testing.T) {
167		tests := []struct {
168			name                    string
169			parent, sub, metaT, now time.Duration // offsets from actBase
170			want                    time.Duration
171		}{
172			{"parent newest", 5 * time.Minute, time.Minute, 2 * time.Minute, time.Hour, 5 * time.Minute},
173			{"sub-agent transcript newest", time.Minute, 7 * time.Minute, 2 * time.Minute, time.Hour, 7 * time.Minute},
174			{"meta newest", time.Minute, 2 * time.Minute, 9 * time.Minute, time.Hour, 9 * time.Minute},
175			{"future mtime counts as the read time", time.Minute, 2 * time.Minute, time.Hour, 10 * time.Minute, 10 * time.Minute},
176		}
177		for _, tc := range tests {
178			t.Run(tc.name, func(t *testing.T) {
179				setClock(t, actBase.Add(tc.now))
180				s := newSess(t)
181				s.putAt(s.parent(), ln("p1"), actBase.Add(tc.parent))
182				s.putAt(s.sub("a1"), ln("s1"), actBase.Add(tc.sub))
183				s.putAt(s.metaPath("a1"), []byte(metaFinished), actBase.Add(tc.metaT))
184				a := NewAggregate(s.parent())
185				readApply(t, a)
186				if got, want := a.Activity().LastChange, actBase.Add(tc.want); !got.Equal(want) {
187					t.Errorf("LastChange = %v, want %v", got, want)
188				}
189			})
190		}
191	}
192	
193	// LastChange follows what changed, not what was looked at: an empty delta
194	// (including one where only an mtime moved) does not advance it, a non-empty
195	// one does and un-settles the session again.
196	func TestActivityFollowsRealChanges(t *testing.T) {
197		clock := setClock(t, actBase)
198		s := newSess(t)
199		s.build(metaSet{"a1": metaFinished}, actBase)
200		a := NewAggregate(s.parent())
201		readApply(t, a)
202		if got := a.Activity(); !got.LastChange.Equal(actBase) || got.Unfinished != 0 {
203			t.Fatalf("after the first read: %+v, want LastChange %v and no unfinished", got, actBase)
204		}
205		if !a.Activity().Settled(actBase.Add(actQuiet), actQuiet) {
206			t.Fatal("a finished session read once is settled after quiet")
207		}
208	
209		// An empty read much later: nothing changed, so LastChange stays.
210		*clock = actBase.Add(time.Hour)
211		if d := readApply(t, a); !d.Empty() {
212			t.Fatal("nothing was written, the delta must be Empty")
213		}
214		if got := a.Activity().LastChange; !got.Equal(actBase) {
215			t.Errorf("an Empty delta moved LastChange to %v", got)
216		}
217	
218		// Only the mtime moves (same size, same content): still not a change.
219		touch(t, s.parent(), actBase.Add(2*time.Hour))
220		*clock = actBase.Add(2 * time.Hour)
221		if d := readApply(t, a); !d.Empty() {
222			t.Fatal("an mtime alone must leave the delta Empty")
223		}
224		if got := a.Activity().LastChange; !got.Equal(actBase) {
225			t.Errorf("a bare mtime change moved LastChange to %v", got)
226		}
227	
228		// New lines: a real change.
229		at := actBase.Add(3 * time.Hour)
230		*clock = at
231		appendFile(t, s.parent(), ln("p3"))
232		touch(t, s.parent(), at)
233		if d := readApply(t, a); d.Empty() {
234			t.Fatal("appended lines must give a non-empty delta")
235		}
236		if got := a.Activity().LastChange; !got.Equal(at) {
237			t.Fatalf("LastChange = %v, want %v", got, at)
238		}
239		act := a.Activity()
240		if act.Settled(at.Add(actQuiet-time.Nanosecond), actQuiet) {
241			t.Error("a new change must un-settle the session until quiet has passed again")
242		}
243		if !act.Settled(at.Add(actQuiet), actQuiet) {
244			t.Error("settled again once quiet has passed without change")
245		}
246	
247		// A sub-agent flips to unfinished (same-size meta): news, and it blocks.
248		at = actBase.Add(4 * time.Hour)
249		*clock = at
250		s.putAt(s.metaPath("a1"), []byte(metaUnfinished), at)
251		if d := readApply(t, a); d.Empty() {
252			t.Fatal("a meta change must give a non-empty delta")
253		}
254		act = a.Activity()
255		if act.Unfinished != 1 || !act.LastChange.Equal(at) {
256			t.Fatalf("after the flip: %+v, want 1 unfinished and LastChange %v", act, at)
257		}
258		if act.Settled(at.Add(1000*time.Hour), actQuiet) {
259			t.Error("an unfinished sub-agent keeps the session active however old")
260		}
261	
262		// ... and back to finished.
263		at = actBase.Add(5 * time.Hour)
264		*clock = at
265		s.putAt(s.metaPath("a1"), []byte(metaFinished), at)
266		readApply(t, a)
267		act = a.Activity()
268		if act.Unfinished != 0 || !act.LastChange.Equal(at) {
269			t.Fatalf("after finishing: %+v, want 0 unfinished and LastChange %v", act, at)
270		}
271		if act.Settled(at.Add(actQuiet-time.Nanosecond), actQuiet) || !act.Settled(at.Add(actQuiet), actQuiet) {
272			t.Error("finishing is a change: settled only after quiet from that moment")
273		}
274	}
275	
276	// A Full delta (here: the cursor is rewound) recomputes the activity from the
277	// files; it does not keep a stale unfinished count.
278	func TestActivityAfterRewoundCursor(t *testing.T) {
279		setClock(t, actBase)
280		s := newSess(t)
281		s.build(metaSet{"a1": metaUnfinished}, actBase)
282		a := NewAggregate(s.parent())
283		readApply(t, a)
284		touch(t, s.metaPath("a1"), actBase)
285		s.putAt(s.metaPath("a1"), []byte(metaFinished), actBase)
286		d, err := ReadDelta(a.Cursor().Rewound())
287		if err != nil {
288			t.Fatal(err)
289		}
290		if err := a.Apply(d); err != nil {
291			t.Fatal(err)
292		}
293		if got := a.Activity().Unfinished; got != 0 {
294			t.Errorf("Unfinished = %d after a Full read of a finished session, want 0", got)
295		}
296	}
297	
298	// The parent cannot be opened but ReadDelta reports no error: the delta
299	// carries IssueOpenFailed on the parent. Decision: such a session is NEVER
300	// settled, whatever else is quiet, so a poller keeps retrying and a transient
301	// failure heals. It is settled again after a successful read plus quiet.
302	func TestActivityWithAnUnreadableParent(t *testing.T) {
303		far := actBase.Add(1000 * time.Hour)
304		for _, tc := range []struct {
305			name string
306			meta string
307		}{
308			{"all sub-agents finished", metaFinished},
309			{"sub-agent unknown", metaUnknown},
310		} {
311			t.Run(tc.name, func(t *testing.T) {
312				clock := setClock(t, actBase)
313				s := newSess(t)
314				s.build(metaSet{"a1": tc.meta}, actBase)
315				orig := openTranscript
316				failing := true
317				swapOpen(t, func(path string) (transcriptFile, error) {
318					if failing && path == s.parent() {
319						return nil, errors.New("injected open failure")
320					}
321					return orig(path)
322				})
323				a := NewAggregate(s.parent())
324				readApply(t, a)
325				if !hasIssue(a.Usage(), incSessUUID+".jsonl", IssueOpenFailed) {
326					t.Fatal("setup: the parent must carry IssueOpenFailed")
327				}
328				if a.Activity().Settled(far, actQuiet) {
329					t.Error("an unreadable parent must keep the session unsettled, however quiet")
330				}
331				*clock = far // still failing on later passes: still unsettled
332				readApply(t, a)
333				if a.Activity().Settled(far.Add(time.Hour), actQuiet) {
334					t.Error("still unsettled while the parent stays unreadable")
335				}
336				failing = false
337				readApply(t, a) // the issue clears
338				if hasIssue(a.Usage(), incSessUUID+".jsonl", IssueOpenFailed) {
339					t.Fatal("setup: the issue must clear once the parent opens")
340				}
341				if !a.Activity().Settled(far.Add(time.Hour), actQuiet) {
342					t.Error("settled again after a successful read and quiet")
343				}
344			})
345		}
346	}
347	
348	func TestActivityUnreadableParentAndUnfinishedSubAgent(t *testing.T) {
349		setClock(t, actBase)
350		s := newSess(t)
351		s.build(metaSet{"a1": metaUnfinished}, actBase)
352		orig := openTranscript
353		swapOpen(t, func(path string) (transcriptFile, error) {
354			if path == s.parent() {
355				return nil, errors.New("injected open failure")
356			}
357			return orig(path)
358		})
359		a := NewAggregate(s.parent())
360		readApply(t, a)
361		if got := a.Activity().Unfinished; got != 1 {
362			t.Errorf("Unfinished = %d, want 1 (the sub-agent's meta was read)", got)
363		}
364	}
365	
366	func TestActivityLeaksNoPath(t *testing.T) {
367		setClock(t, actBase)
368		s := newSessIn(t, "SENTINEL-DO-NOT-LEAK-dir")
369		s.build(metaSet{"a1": metaUnfinished}, actBase)
370		a := NewAggregate(s.parent())
371		readApply(t, a)
372		act := a.Activity()
373		for _, out := range []string{fmt.Sprint(act), fmt.Sprintf("%+v", act), fmt.Sprintf("%#v", act)} {
374			if strings.Contains(out, "SENTINEL") || strings.Contains(out, s.dir) || strings.Contains(out, incSessUUID) {
375				t.Errorf("Activity prints a path or a name: %q", out)
376			}
377		}
378		typ := reflect.TypeOf(act)
379		for i := 0; i < typ.NumField(); i++ {
380			f := typ.Field(i)
381			if f.Type != reflect.TypeOf(time.Time{}) && f.Type.Kind() != reflect.Int && f.Type.Kind() != reflect.Bool {
382				t.Errorf("field %s has type %v: Activity carries a time and a count, nothing that can hold a path", f.Name, f.Type)
383			}
384		}
385	}
386	
387	// Criterion 1, testable here: once a pass has read everything, a session where
388	// nothing is written costs no transcript open and no meta read, settled or not.
389	func TestQuietSessionIsNeverOpenedAgain(t *testing.T) {
390		tests := []struct {
391			name        string
392			meta        string
393			wantSettled bool
394		}{
395			{"finished sub-agents, settled", metaFinished, true},
396			{"unknown sub-agents, settled", metaUnknown, true},
397			{"unfinished sub-agents, still active", metaUnfinished, false},
398		}
399		for _, tc := range tests {
400			t.Run(tc.name, func(t *testing.T) {
401				setClock(t, actBase)
402				s := newSess(t)
403				s.build(metaSet{"a1": tc.meta, "b2": tc.meta, "c3": tc.meta}, actBase)
404				p := countOpens(t)
405				metas := countMetaReads(t)
406				a := NewAggregate(s.parent())
407				if d := readApply(t, a); d.Empty() {
408					t.Fatal("the first delta cannot be Empty")
409				}
410				if p.calls != 4 || *metas != 3 {
411					t.Fatalf("first pass: %d open calls, %d meta reads, want 4 and 3", p.calls, *metas)
412				}
413				act := a.Activity()
414				far := actBase.Add(24 * time.Hour)
415				if got := act.Settled(far, actQuiet); got != tc.wantSettled {
416					t.Fatalf("Settled(far) = %v, want %v", got, tc.wantSettled)
417				}
418				*p, *metas = probe{}, 0
419				for i := 0; i < 10; i++ {
420					if d := readApply(t, a); !d.Empty() || d.Full() {
421						t.Fatalf("pass %d: Empty=%v Full=%v, want true and false", i, d.Empty(), d.Full())
422					}
423				}
424				if p.calls != 0 || *metas != 0 {
425					t.Errorf("10 quiet passes: %d open calls, %d meta reads, want 0 and 0", p.calls, *metas)
426				}
427				if got := a.Activity(); got != act {
428					t.Errorf("Activity changed across quiet passes: %+v then %+v", act, got)
429				}
430			})
431		}
432	}
