// Settled reports whether polling can stop: something was applied, the parent
// is readable, no sub-agent is unfinished, and nothing changed for at least
// quiet before now.
func (a Activity) Settled(now time.Time, quiet time.Duration) bool {
	return !a.LastChange.IsZero() && !a.unreadable && a.Unfinished == 0 && now.Sub(a.LastChange) >= quiet
}

// Activity returns what the reads applied so far say about the session's life.
func (a *Aggregate) Activity() Activity {
	act := Activity{LastChange: a.lastMod}
	for _, m := range a.metas {
		if m.path != "" && !m.unreadable && m.state == StateUnfinished {
			act.Unfinished++
		}
	}
	if len(a.files) > 0 {
		p := a.files[0]
		act.unreadable = p.hasIssue && p.issue == IssueOpenFailed
	}
