591	// newestMod returns the newest mtime among the files and metas of d, clamped
592	// to the time d was read.
593	func newestMod(d Delta) time.Time {
594		var newest time.Time
595		for _, fc := range d.files {
596			if fc.modTime.After(newest) {
597				newest = fc.modTime
598			}
599		}
600		for _, m := range d.metas {
601			if m.modTime.After(newest) {
602				newest = m.modTime
603			}
604		}
605		if newest.After(d.read) {
606			newest = d.read
607		}
608		return newest
